<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Climate Change 2023 — IPCC AR6 Synthesis Report</title>
<script src="/app/vendor/infographic.min.js"></script>
<style>
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800;900&display=swap');

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  background: #0b1120;
  color: #e2e8f0;
}

.poster {
  width: 1600px;
  min-height: 2263px; /* A0 portrait ratio at ~150dpi */
  margin: 0 auto;
  background: linear-gradient(180deg, #0f172a 0%, #1e293b 40%, #0f172a 100%);
  display: flex;
  flex-direction: column;
  gap: 0;
}

/* HEADER */
.header {
  padding: 48px 64px 32px;
  border-bottom: 4px solid #dc2626;
  background: linear-gradient(135deg, #0f172a 0%, #1e3a5f 100%);
}

.header-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 24px;
}

.badge {
  background: #dc2626;
  color: white;
  padding: 6px 16px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  border-radius: 4px;
}

.header h1 {
  font-size: 56px;
  font-weight: 900;
  line-height: 1.1;
  color: #f8fafc;
  margin-bottom: 16px;
  letter-spacing: -0.02em;
}

.header h1 span {
  color: #f59e0b;
}

.subtitle {
  font-size: 22px;
  color: #94a3b8;
  line-height: 1.5;
  max-width: 1100px;
}

/* SECTIONS */
.section {
  padding: 36px 64px;
  border-bottom: 1px solid rgba(148,163,184,0.15);
}

.section-title {
  font-size: 28px;
  font-weight: 800;
  color: #f8fafc;
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.section-title .dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #f59e0b;
}

.section-desc {
  font-size: 16px;
  color: #94a3b8;
  margin-bottom: 24px;
  line-height: 1.6;
}

/* METRICS GRID — custom CSS for impact */
.metrics-section {
  background: linear-gradient(135deg, #1e293b 0%, #0f172a 100%);
  padding: 40px 64px;
}

.metrics-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.metric-card {
  background: rgba(30,41,59,0.8);
  border: 1px solid rgba(148,163,184,0.2);
  border-radius: 12px;
  padding: 24px;
  text-align: center;
  transition: transform 0.2s;
}

.metric-card.highlight {
  border-color: #dc2626;
  background: linear-gradient(135deg, rgba(220,38,38,0.15) 0%, rgba(30,41,59,0.9) 100%);
}

.metric-card.highlight-blue {
  border-color: #0ea5e9;
  background: linear-gradient(135deg, rgba(14,165,233,0.12) 0%, rgba(30,41,59,0.9) 100%);
}

.metric-value {
  font-size: 42px;
  font-weight: 900;
  color: #f59e0b;
  line-height: 1.1;
  margin-bottom: 8px;
}

.metric-card.highlight .metric-value {
  color: #ef4444;
}

.metric-card.highlight-blue .metric-value {
  color: #38bdf8;
}

.metric-label {
  font-size: 13px;
  color: #94a3b8;
  line-height: 1.4;
}

/* FULL WIDTH METRIC */
.full-width-metric {
  grid-column: span 2;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
}

.full-width-metric .metric-value {
  font-size: 52px;
}

.full-width-metric .metric-label {
  font-size: 15px;
  text-align: left;
  max-width: 280px;
}

/* INFOGRAPHIC CONTAINERS */
.infographic-wrap {
  margin-top: 16px;
  border-radius: 12px;
  overflow: hidden;
  background: rgba(15,23,42,0.5);
}

/* TWO COLUMN LAYOUT */
.two-col {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
}

/* SSP TABLE */
.ssp-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 16px;
  font-size: 15px;
}
.ssp-table th {
  background: rgba(245,158,11,0.15);
  color: #f59e0b;
  padding: 12px 16px;
  text-align: left;
  font-weight: 700;
  border-bottom: 2px solid #f59e0b;
}
.ssp-table td {
  padding: 12px 16px;
  border-bottom: 1px solid rgba(148,163,184,0.15);
  color: #cbd5e1;
}
.ssp-table tr:hover td {
  background: rgba(245,158,11,0.05);
}
.ssp-scenario {
  font-weight: 700;
  color: #f8fafc;
}
.temp-high { color: #ef4444; font-weight: 700; }
.temp-med { color: #f59e0b; font-weight: 700; }
.temp-low { color: #38bdf8; font-weight: 700; }

/* RISKS GRID */
.risks-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-top: 16px;
}
.risk-card {
  background: rgba(30,41,59,0.6);
  border: 1px solid rgba(148,163,184,0.15);
  border-radius: 12px;
  padding: 24px;
}
.risk-card h4 {
  font-size: 18px;
  font-weight: 700;
  color: #f59e0b;
  margin-bottom: 10px;
}
.risk-card p {
  font-size: 14px;
  color: #94a3b8;
  line-height: 1.6;
}

/* CTA SECTION */
.cta-section {
  background: linear-gradient(135deg, #7f1d1d 0%, #450a0a 50%, #0f172a 100%);
  padding: 48px 64px;
  text-align: center;
}
.cta-section .section-title {
  justify-content: center;
  font-size: 36px;
}
.cta-text {
  font-size: 20px;
  color: #fecaca;
  line-height: 1.7;
  max-width: 1000px;
  margin: 0 auto 32px;
}
.cta-highlight {
  background: rgba(220,38,38,0.25);
  border: 1px solid #ef4444;
  border-radius: 12px;
  padding: 24px 32px;
  display: inline-block;
  margin-top: 8px;
}
.cta-highlight .big {
  font-size: 48px;
  font-weight: 900;
  color: #fca5a5;
}
.cta-highlight .small {
  font-size: 16px;
  color: #fca5a5;
}

.footer {
  padding: 20px 64px;
  text-align: center;
  font-size: 12px;
  color: #64748b;
  border-top: 1px solid rgba(148,163,184,0.1);
}

/* Pathway comparison */
.pathway-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  margin-top: 16px;
}
.pathway-card {
  background: rgba(30,41,59,0.6);
  border-radius: 12px;
  padding: 28px;
  border-left: 4px solid;
}
.pathway-card.target-15 { border-left-color: #0ea5e9; }
.pathway-card.target-20 { border-left-color: #f59e0b; }
.pathway-card h4 {
  font-size: 22px;
  font-weight: 800;
  margin-bottom: 16px;
}
.pathway-card.target-15 h4 { color: #38bdf8; }
.pathway-card.target-20 h4 { color: #f59e0b; }
.pathway-card .req {
  font-size: 32px;
  font-weight: 900;
  margin-bottom: 8px;
}
.pathway-card.target-15 .req { color: #38bdf8; }
.pathway-card.target-20 .req { color: #f59e0b; }
.pathway-card .req-label {
  font-size: 14px;
  color: #94a3b8;
  margin-bottom: 16px;
}
.pathway-card .detail {
  font-size: 14px;
  color: #cbd5e1;
  line-height: 1.6;
}
</style>
</head>
<body>
<div class="poster">

  <!-- HEADER -->
  <div class="header">
    <div class="header-top">
      <div>
        <div class="badge">IPCC AR6 Synthesis Report 2023</div>
      </div>
    </div>
    <h1>Climate Change 2023:<br><span>Key Findings from the IPCC Sixth Assessment Synthesis Report</span></h1>
    <p class="subtitle">A visual summary of the most critical findings from the IPCC AR6 cycle — observed changes, future projections, and urgent pathways for climate action.</p>
  </div>

  <!-- METRICS -->
  <div class="metrics-section">
    <div class="section-title"><span class="dot"></span> Seven Headline Metrics</div>
    <div class="metrics-grid">
      <div class="metric-card">
        <div class="metric-value">+1.1°C</div>
        <div class="metric-label">Global surface temperature increase<br>(2011–2020 vs. 1850–1900)</div>
      </div>
      <div class="metric-card highlight-blue">
        <div class="metric-value">410 ppm</div>
        <div class="metric-label">CO₂ concentration in 2019<br>highest in 2 million years</div>
      </div>
      <div class="metric-card">
        <div class="metric-value">~59 Gt</div>
        <div class="metric-label">Global GHG emissions in 2019<br>CO₂-equivalent</div>
      </div>
      <div class="metric-card highlight-blue">
        <div class="metric-value">~500 Gt</div>
        <div class="metric-label">Remaining carbon budget for 1.5°C<br>(50% likelihood, from 2020)</div>
      </div>
      <div class="metric-card highlight">
        <div class="metric-value">43%</div>
        <div class="metric-label">Required GHG reduction by 2030<br>below 2019 levels for 1.5°C pathway</div>
      </div>
      <div class="metric-card">
        <div class="metric-value">~0.20 m</div>
        <div class="metric-label">Sea level rise<br>(1901–2018)</div>
      </div>
      <div class="metric-card highlight full-width-metric">
        <div class="metric-value">3.3–3.6B</div>
        <div class="metric-label">People exposed to severe climate hazards — the largest vulnerable population ever quantified by the IPCC</div>
      </div>
      <div class="metric-card highlight-blue">
        <div class="metric-value">Net Zero</div>
        <div class="metric-label">CO₂ by ~2050<br>for 1.5°C limit</div>
      </div>
    </div>
  </div>

  <!-- OBSERVED CHANGES -->
  <div class="section">
    <div class="section-title"><span class="dot"></span> Observed Changes and Current State</div>
    <p class="section-desc">Human-caused climate change is already affecting every region on Earth, with widespread and intensifying consequences.</p>
    <div id="observed-chart" class="infographic-wrap" style="height: 340px;"></div>
  </div>

  <!-- FUTURE PROJECTIONS -->
  <div class="section">
    <div class="section-title"><span class="dot" style="background:#ef4444"></span> Future Projections Under Different Scenarios</div>
    <p class="section-desc">The AR6 uses Shared Socioeconomic Pathways (SSPs) to project future climate outcomes. Choices made this decade determine which pathway unfolds.</p>
    <table class="ssp-table">
      <thead>
        <tr><th>Scenario</th><th>Projected Warming by 2100</th><th>Description</th><th>Sea Level Rise by 2100</th></tr>
      </thead>
      <tbody>
        <tr><td class="ssp-scenario temp-low">SSP1-1.9</td><td class="temp-low">~1.4°C</td><td>Very low emissions, sustainability focus</td><td>0.28–0.55 m</td></tr>
        <tr><td class="ssp-scenario temp-low">SSP1-2.6</td><td class="temp-low">~1.8°C</td><td>Low emissions</td><td>moderate</td></tr>
        <tr><td class="ssp-scenario temp-med">SSP2-4.5</td><td class="temp-med">~2.7°C</td><td>Intermediate emissions</td><td>moderate-high</td></tr>
        <tr><td class="ssp-scenario temp-high">SSP3-7.0</td><td class="temp-high">~3.6°C</td><td>High emissions</td><td>high</td></tr>
        <tr><td class="ssp-scenario temp-high">SSP5-8.5</td><td class="temp-high">~4.4°C</td><td>Very high emissions, fossil-fuel intensive</td><td>0.63–1.01 m</td></tr>
      </tbody>
    </table>
    <div style="margin-top:20px; display:grid; grid-template-columns: 1fr 1fr; gap:20px;">
      <div id="ssp-chart" class="infographic-wrap" style="height: 300px;"></div>
      <div id="sea-level-chart" class="infographic-wrap" style="height: 300px;"></div>
    </div>
  </div>

  <!-- RISKS -->
  <div class="section">
    <div class="section-title"><span class="dot" style="background:#dc2626"></span> Risks, Vulnerabilities, and Cascading Impacts</div>
    <p class="section-desc">Approximately <strong style="color:#fca5a5;">3.3 to 3.6 billion people</strong> live in contexts highly vulnerable to climate change. Climate hazards interact with poverty, inequality, and ecosystem degradation to produce cascading risks.</p>
    <div class="risks-grid">
      <div class="risk-card">
        <h4>🌾 Food Security</h4>
        <p>Crop yield growth rates have slowed in many regions. Fisheries productivity is declining in tropical zones. Beyond 1.5°C, up to 14% of terrestrial species face very high extinction risk.</p>
      </div>
      <div class="risk-card">
        <h4>💧 Water Stress</h4>
        <p>Over half the world's population currently experiences severe water scarcity for at least one month per year. Drought intensity and frequency are increasing across vulnerable regions.</p>
      </div>
      <div class="risk-card">
        <h4>🏥 Health</h4>
        <p>Heat-related mortality and vector-borne disease ranges are expanding. Mental health impacts from extreme events and displacement are growing.</p>
      </div>
    </div>
  </div>

  <!-- MITIGATION -->
  <div class="section">
    <div class="section-title"><span class="dot" style="background:#0ea5e9"></span> Mitigation and Adaptation Pathways</div>
    <p class="section-desc">Immediate, deep, and sustained emissions reductions across all sectors are essential to secure a liveable future.</p>
    <div class="pathway-grid">
      <div class="pathway-card target-15">
        <h4>1.5°C Target</h4>
        <div class="req">43%</div>
        <div class="req-label">reduction below 2019 levels by 2030</div>
        <div class="detail">Net zero CO₂ by around <strong>2050</strong>. Remaining carbon budget: ~500 GtCO₂ (from 2020). Requires rapid decarbonization, electrification, demand-side efficiency, and protection of carbon sinks.</div>
      </div>
      <div class="pathway-card target-20">
        <h4>2.0°C Target</h4>
        <div class="req">27%</div>
        <div class="req-label">reduction below 2019 levels by 2030</div>
        <div class="detail">Net zero CO₂ by around <strong>2070</strong>. Higher residual climate risks. More costly adaptation. Greater irreversible losses in biodiversity and cryosphere.</div>
      </div>
    </div>
    <div id="mitigation-chart" class="infographic-wrap" style="height: 280px; margin-top: 20px;"></div>
  </div>

  <!-- CALL TO ACTION -->
  <div class="cta-section">
    <div class="section-title" style="color:#fca5a5;"><span class="dot" style="background:#fca5a5"></span> The Narrowing Window for Action</div>
    <p class="cta-text">The choices made in <strong>this decade</strong> will determine whether warming can be held to 1.5°C or 2°C. Delayed action increases costs, locks in high-carbon infrastructure, and reduces feasibility. Climate finance flows remain insufficient — falling short of needs by a factor of <strong>3 to 6</strong> for adaptation alone.</p>
    <div class="cta-highlight">
      <div class="big">ACT NOW</div>
      <div class="small">Immediate, deep, and sustained emissions reductions across all sectors are essential.</div>
    </div>
  </div>

  <div class="footer">
    Source: IPCC, 2023. AR6 Synthesis Report: Climate Change 2023. Intergovernmental Panel on Climate Change. | Poster generated for Climate Science Conference dissemination.
  </div>

</div>

<script>
// Observed changes bar chart
const observedChart = new AntVInfographic.Infographic({
  container: '#observed-chart',
  width: '100%',
  height: '100%',
});
observedChart.render(`infographic chart-column-simple
data
  title Observed Climate Indicators
  values
    - label Temp Rise
      value 1.1
    - label CO₂ (ppm/100)
      value 4.1
    - label GHG (Gt)
      value 59
    - label Sea Level (m×100)
      value 20
    - label Arctic Ice Loss (%)
      value 40
theme
  palette #f59e0b #ef4444 #f97316 #0ea5e9 #8b5cf6
`);

// SSP warming trajectory line chart
const sspChart = new AntVInfographic.Infographic({
  container: '#ssp-chart',
  width: '100%',
  height: '100%',
});
sspChart.render(`infographic chart-line-plain-text
data
  title Projected Global Warming by 2100 (°C)
  desc Diverging pathways based on emissions choices
  values
    - label SSP1-1.9
      value 1.4
    - label SSP1-2.6
      value 1.8
    - label SSP2-4.5
      value 2.7
    - label SSP3-7.0
      value 3.6
    - label SSP5-8.5
      value 4.4
theme
  palette #ef4444 #f59e0b #f97316 #dc2626 #7f1d1d
`);

// Sea level chart
const seaLevelChart = new AntVInfographic.Infographic({
  container: '#sea-level-chart',
  width: '100%',
  height: '100%',
});
seaLevelChart.render(`infographic chart-bar-plain-text
data
  title Sea Level Rise by 2100 (m)
  values
    - label SSP1-1.9
      value 0.42
    - label SSP5-8.5
      value 0.82
theme
  palette #38bdf8 #ef4444
`);

// Mitigation comparison
const mitigationChart = new AntVInfographic.Infographic({
  container: '#mitigation-chart',
  width: '100%',
  height: '100%',
});
mitigationChart.render(`infographic compare-binary-horizontal-badge-card-arrow
data
  title Emissions Reduction Requirements
  compares
    - label 1.5°C Pathway
      children
        - label By 2030
          value 43
          desc percent below 2019
          icon arrow down
        - label Net Zero
          value 2050
          desc target year
          icon calendar check
    - label 2.0°C Pathway
      children
        - label By 2030
          value 27
          desc percent below 2019
          icon arrow down
        - label Net Zero
          value 2070
          desc target year
          icon calendar
theme
  palette #0ea5e9 #f59e0b
`);
</script>
</body>
</html>
